namespace ghidra.lisa.pcode.contexts;

using ghidra.program.model.address;

public class SymbolVarnodeContext : VarnodeContext {

	private string context;
	private int size;

	/*
	 * This class is essentially a dummy context for the case where the varnode's id is a memory address
	 */
	public SymbolVarnodeContext(string name, Address context) : this(context)
    {
		this.context = name;
	}

	public SymbolVarnodeContext(Address context) : base(null)
    {
		this.context = context.toString();
		size = context.getPointerSize();
	}

	/* @Override */
	public bool isConstant() {
		return false;
	}

	/* @Override */
	public int getSize() {
		return size;
	}

	/* @Override */
	public long getOffset() {
		return 0;
	}

	/* @Override */
	public string getText() {
		return context;
	}

}
